import base64,zlib,os
f_dashboard_html=""
with open("/var/www/luxe-talent/dist/dashboard.html","wb") as f: f.write(zlib.decompress(base64.b64decode(f_dashboard_html)))
print("dashboard.html:",len(zlib.decompress(base64.b64decode(f_dashboard_html))),"bytes")
f_leads_php=""
with open("/var/www/luxe-talent/dist/api/leads.php","wb") as f: f.write(zlib.decompress(base64.b64decode(f_leads_php)))
print("leads.php:",len(zlib.decompress(base64.b64decode(f_leads_php))),"bytes")
f_tasks_php=""
with open("/var/www/luxe-talent/dist/api/tasks.php","wb") as f: f.write(zlib.decompress(base64.b64decode(f_tasks_php)))
print("tasks.php:",len(zlib.decompress(base64.b64decode(f_tasks_php))),"bytes")
for f in ["/var/www/luxe-talent/dist/dashboard.html","/var/www/luxe-talent/dist/api/leads.php","/var/www/luxe-talent/dist/api/tasks.php"]: os.system("chown apache:apache "+f)
print("Done!")